import{_ as a,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 6 章 记忆系统：让 AI 越来越懂你（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第6章 记忆系统：让 AI 越来越懂你（易懂版）.md","filePath":"easy/第6章 记忆系统：让 AI 越来越懂你（易懂版）.md"}'),n={name:"easy/第6章 记忆系统：让 AI 越来越懂你（易懂版）.md"};function s(l,t,d,i,h,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-6-章-记忆系统-让-ai-越来越懂你-易懂版" tabindex="-1">第 6 章 记忆系统：让 AI 越来越懂你（易懂版） <a class="header-anchor" href="#第-6-章-记忆系统-让-ai-越来越懂你-易懂版" aria-label="Permalink to &quot;第 6 章 记忆系统：让 AI 越来越懂你（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 6 章 记忆系统：让 AI 越来越懂你（完整版）](../../bluebook/第一篇 使用手册：先把我用起来/第 6 章 记忆系统：让 AI 越来越懂你.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>我有一本&quot;记性本&quot;，会记住你的事——记住的越多，越不用你重复交代。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>老同事为什么好配合？因为他记得：<strong>你爱喝什么、项目进度到哪、上次哪个方案被老板毙了</strong>。</p><p>我的记忆系统就是这个&quot;老同事记性&quot;——<strong>跨对话记得你</strong>，而不是每次见面都像陌生人。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>我会自动记</strong>：你提的需求、你纠正过我的地方、项目背景——我会悄悄存进记忆文件。</li><li><strong>记忆分四类</strong>：<table tabindex="0"><thead><tr><th>类型</th><th>记什么</th><th>比方</th></tr></thead><tbody><tr><td><strong>用户</strong></td><td>你是谁、什么背景</td><td>你的档案</td></tr><tr><td><strong>反馈</strong></td><td>你纠正过我什么</td><td>你的&quot;口味&quot;</td></tr><tr><td><strong>项目</strong></td><td>项目背景、进度</td><td>项目台账</td></tr><tr><td><strong>参考</strong></td><td>你常用的资料、约定</td><td>你的常用手册</td></tr></tbody></table></li><li><strong>有索引不混乱</strong>：MEMORY.md 是总目录，一条条指向具体记忆——想看哪条翻哪条。</li></ol><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p>你今天说：&quot;以后周报都用表格格式。&quot; 下次你说&quot;生成周报&quot;，我会<strong>主动用表格</strong>，不用你再交代一次。👌</p></blockquote><h2 id="怎么用好记忆" tabindex="-1">怎么用好记忆？ <a class="header-anchor" href="#怎么用好记忆" aria-label="Permalink to &quot;怎么用好记忆？&quot;">​</a></h2><ul><li>✅ 重要偏好直接说：&quot;记住，我所有报告都要 PDF&quot;；</li><li>✅ 纠正我时顺便说一句：&quot;以后别用英文标题&quot;——我记下来；</li><li>✅ 定期看看我记了什么（记忆文件），<strong>发现记错了就让我改/删</strong>。</li></ul><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 以为记忆是&quot;读心术&quot;——它只记你<strong>说过</strong>的，不是猜出来的；</li><li>❌ 以为记忆万能——复杂任务还是要你<strong>当场讲清楚</strong>；</li><li>❌ 不管它记了什么——<strong>要定期检查，记错要删</strong>（尤其隐私信息）。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>我有一本记性本，越用越懂你；但记什么你说了算，随时能查、能改、能删。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>今天就给我一条&quot;长期偏好&quot;试试：比如&quot;以后所有文档用中文标题&quot;。<strong>看下次我会不会主动遵守。</strong></p><p>👉 [下一章：计划模式与长任务执行（易懂版）](第7章 计划模式与长任务执行（易懂版）.md)</p>',20)])])}const c=a(n,[["render",s]]);export{q as __pageData,c as default};
